import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    y = [n + 1] + [0] * (n + 1)
    for k in range(n):
        y[data[2 * k + 1]] = data[2 * k + 2]

    # A canonical set of pivots consists of every isolated ball in
    # the final configuration. Consecutive pivots bound a rectangle
    # whose surviving balls must have no isolated ball.
    dp = [0] * (n + 2)
    dp[0] = 1
    for j in range(1, n + 2):
        low = y[j]
        total = 0
        for i in range(j):
            high = y[i]
            if high <= low or dp[i] == 0:
                continue
            a = [y[k] for k in range(i + 1, j) if low < y[k] < high]
            m = len(a)
            if m:
                suffix = [0] * (m + 1)
                for k in range(m - 1, -1, -1):
                    suffix[k] = max(a[k], suffix[k + 1])
                minimum = n + 1
                for k, v in enumerate(a):
                    if v < minimum:
                        if v > suffix[k + 1]:
                            break
                        minimum = v
                else:
                    total += dp[i]
            else:
                total += dp[i]
        dp[j] = total % MOD
    print(dp[-1])


if __name__ == '__main__':
    main()

