import sys

MOD = 998244353

def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    m = next(it)
    bound = [[n] * n for _ in range(n)]
    for _ in range(m):
        l = next(it) - 1
        r = next(it) - 1
        x = next(it) - 1
        if r < bound[l][x]:
            bound[l][x] = r

    # bound[l][k]: smallest right endpoint of a condition at k
    # whose left endpoint is at least l.
    for l in range(n - 2, -1, -1):
        a = bound[l]
        b = bound[l + 1]
        for k in range(n):
            if b[k] < a[k]:
                a[k] = b[k]

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # dp[l][r] is the valid count divided by (r-l)!.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    # cols[r][k] stores dp[k+1][r].
    cols = [[0] * n for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][i] = 1
        if i:
            cols[i][i - 1] = 1

    for l in range(n - 1, -1, -1):
        row = dp[l]
        limits = bound[l]
        for r in range(l + 1, n + 1):
            col = cols[r]
            total = 0
            for k in range(l, r):
                if limits[k] >= r:
                    total += row[k] * col[k]
            value = total % MOD * inv[r - l] % MOD
            row[r] = value
            if l:
                col[l - 1] = value

    answer = dp[0][n]
    for i in range(2, n + 1):
        answer = answer * i % MOD
    print(answer)

if __name__ == '__main__':
    main()

