import sys
from collections import deque
from array import array

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [x - 1 for x in data[2:]]
    indegree = [0] * n
    for v in a:
        indegree[v] += 1

    queue = deque(i for i in range(n) if indegree[i] == 0)
    dp = [None] * n

    # dp[v][k-1] counts assignments below v when its value is k.
    # None represents an array consisting entirely of ones.
    while queue:
        v = queue.popleft()
        parent = a[v]
        current = dp[v]
        target = dp[parent]
        if current is None:
            if target is None:
                dp[parent] = array('I', range(1, m + 1))
            else:
                for j in range(m):
                    target[j] = target[j] * (j + 1) % MOD
        else:
            total = 0
            if target is None:
                for j in range(m):
                    total = (total + current[j]) % MOD
                    current[j] = total
                dp[parent] = current
            else:
                for j in range(m):
                    total = (total + current[j]) % MOD
                    target[j] = target[j] * total % MOD
        dp[v] = None
        indegree[parent] -= 1
        if indegree[parent] == 0:
            queue.append(parent)

    # All vertices on a directed cycle must have the same value.
    answer = 1
    for v in range(n):
        if indegree[v] == 0:
            continue
        product = None
        u = v
        while indegree[u]:
            indegree[u] = 0
            current = dp[u]
            if current is not None:
                if product is None:
                    product = current
                else:
                    for j in range(m):
                        product[j] = product[j] * current[j] % MOD
            u = a[u]
        count = m if product is None else sum(product) % MOD
        answer = answer * count % MOD

    print(answer)


if __name__ == '__main__':
    main()

