import sys
import math

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = {}
    for i, x in enumerate(data[1:]):
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][i] = e
            p += 1
        if x > 1:
            if x not in factors:
                factors[x] = [0] * (n - 1)
            factors[x][i] = 1

    answer = 1
    for p, exponents in factors.items():
        g = 0
        for e in exponents:
            g = math.gcd(g, e)
        if g > 1:
            exponents = [e // g for e in exponents]
        base = pow(p, g, MOD)
        limit = max(sum(exponents), max(exponents) * n)
        powers = [1] * (limit + 1)
        for j in range(limit):
            powers[j + 1] = powers[j] * base % MOD

        # Heights are normalized so the minimum in the prefix is zero.
        dp = [1]
        for i, e in enumerate(exponents, 1):
            if e == 0:
                dp = [value * powers[h] % MOD for h, value in enumerate(dp)]
                continue
            next_dp = [0] * (len(dp) + e)
            for h, value in enumerate(dp):
                if not value:
                    continue
                t = h + e
                next_dp[t] = (next_dp[t] + value * powers[t]) % MOD
                if h >= e:
                    t = h - e
                    next_dp[t] = (next_dp[t] + value * powers[t]) % MOD
                else:
                    # Raising all i previous heights restores minimum zero.
                    next_dp[0] = (next_dp[0] + value * powers[(e - h) * i]) % MOD
            dp = next_dp
        answer = answer * (sum(dp) % MOD) % MOD
    print(answer)

if __name__ == '__main__':
    main()

