from collections import Counter
from operator import mul

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    counts = Counter(a)
    values = list(counts)
    k = len(values)
    ans = 0
    p = 1
    out = []
    if k <= 180:
        ids = {v: i for i, v in enumerate(values)}
        rows = [[math.gcd(v, w) for w in values] for v in values]
        weights = [0] * k
        for v in a:
            j = ids[v]
            q = sum(map(mul, weights, rows[j]))
            ans = (2 * ans + q) % MOD
            out.append(str(ans))
            weights[j] = (weights[j] + p) % MOD
            p = p * 2 % MOD
    else:
        m = max(a)
        phi = list(range(m + 1))
        divs = [[] for _ in range(m + 1)]
        for d in range(1, m + 1):
            for v in range(d, m + 1, d):
                divs[v].append(d)
        for d in range(2, m + 1):
            if phi[d] == d:
                for v in range(d, m + 1, d):
                    phi[v] -= phi[v] // d
        heavy = sorted(
            (v for v in values if counts[v] * len(divs[v]) > 3 * n),
            key=lambda v: counts[v] * len(divs[v]), reverse=True
        )[:8]
        h = len(heavy)
        hi = {v: i for i, v in enumerate(heavy)}
        hw = [0] * h
        light = [0] * h
        rows = {v: [math.gcd(v, w) for w in heavy] for v in values} if h else {}
        pairs = {v: [(d, phi[d]) for d in divs[v]] for v in values if v not in hi}
        s = [0] * (m + 1)
        i = 0
        while i < n:
            v = a[i]
            j = i + 1
            while j < n and a[j] == v:
                j += 1
            row = rows[v] if h else []
            if v in hi:
                z = hi[v]
                q = light[z] + sum(map(mul, hw, row))
            else:
                ps = pairs[v]
                q = sum(s[d] * f for d, f in ps)
                if h:
                    q += sum(map(mul, hw, row))
            total = 0
            for _ in range(i, j):
                ans = (2 * ans + q) % MOD
                out.append(str(ans))
                total += p
                q += v * p
                p = p * 2 % MOD
            if v in hi:
                hw[hi[v]] = (hw[hi[v]] + total) % MOD
            else:
                for d, f in ps:
                    s[d] += total
                for z in range(h):
                    light[z] = (light[z] + row[z] * total) % MOD
            i = j
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

