import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    a = data[1:]
    limit = max(a)

    # omega[x] counts prime factors with multiplicity: the pile's Grundy value.
    omega = [0] * (limit + 1)
    for p in range(2, limit + 1):
        if omega[p] == 0:
            power = p
            while power <= limit:
                for multiple in range(power, limit + 1, power):
                    omega[multiple] += 1
                power *= p

    result = 0
    for value in a:
        result ^= omega[value]
    print('Anna' if result else 'Bruno')


