        t = next(it)
        if t == 1:
            e = next(it)-1
            closed[e] = 1
            queries.append((1, e))
        else:
            queries.append((2, next(it)-1, next(it)-1))
    inf = 10**18
    d = [[inf]*n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for e, (a, b, c) in enumerate(edges):
        if not closed[e]:
            d[a][b] = d[b][a] = c
    for k in range(n):
        row = d[k]
        for i in range(n):
            di = d[i]
            v = di[k]
            if v == inf:
                continue
            for j in range(n):
                val = v + row[j]
                if val < di[j]:
                    di[j] = val
    ans = []
    for query in reversed(queries):
        if query[0] == 2:
            v = d[query[1]][query[2]]
            ans.append(str(v if v < inf else -1))
        else:
            a, b, c = edges[query[1]]
            if c >= d[a][b]:
                continue
            ra = d[a][:]
            rb = d[b][:]
            for i in range(n):
                va = ra[i] + c
                vb = rb[i] + c
                if va < rb[i]:
                    base = va
                    row = rb
                elif vb < ra[i]:
                    base = vb
                    row = ra
                else:
