                di = d[i]
                for j in range(i+1, n):
                    val = base + row[j]
                    if val < di[j]:
                        di[j] = val
                        d[j][i] = val
    sys.stdout.write('\n'.join(reversed(ans)))

if __name__ == '__main__':
    main()

