import sys
from math import gcd


def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    budget = next(it)
    processes = []
    upper = budget * 100 + 1

    for _ in range(n):
        a, p, b, q = next(it), next(it), next(it), next(it)
        # Make the first machine at least as cost-efficient as the second.
        if a * q < b * p:
            a, p, b, q = b, q, a, p
        # Larger counts of the second machine can be replaced without
        # increasing cost or changing the resulting capacity.
        options = [(j * b, j * q) for j in range(a // gcd(a, b))]
        processes.append((a, p, options))
        upper = min(upper, budget * a // p + 1)

    def feasible(w):
        total = 0
        for a, p, options in processes:
            best = ((w + a - 1) // a) * p
            for capacity, cost in options:
                if capacity >= w:
                    if cost < best:
                        best = cost
                    break
                cost += ((w - capacity + a - 1) // a) * p
                if cost < best:
                    best = cost
            total += best
            if total > budget:
                return False
        return True

    lo, hi = 0, upper
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    print(lo)


if __name__ == '__main__':
    main()

