class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 1000000007
        limit = min(n, x)
        dp = [0] * (limit + 1)
        dp[0] = 1
        for i in range(1, n + 1):
            for k in range(min(i, limit), 0, -1):
                dp[k] = (dp[k] * k + dp[k - 1]) % mod
            dp[0] = 0
        answer = 0
