class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)
        depth = [0] * (m + 1)
        for i in range(2, m + 1):
            depth[i] = 1 + depth[i.bit_count()]
        valid = [i for i in range(1, m + 1) if depth[i] < k]

        fact = [1] * (m + 1)
        for i in range(1, m + 1):
            fact[i] = fact[i - 1] * i % MOD
        invfact = [1] * (m + 1)
        invfact[m] = pow(fact[m], MOD - 2, MOD)
        for i in range(m, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        answer = 0
        ones = 0
        for pos, ch in enumerate(s):
            if ch == '1':
                # First differ from s here by choosing zero.
                remaining = m - pos - 1
                subtotal = 0
                for r in valid:
                    t = r - ones
                    if t < 0:
                        continue
                    if t > remaining:
                        break
                    subtotal += invfact[t] * invfact[remaining - t] % MOD
                answer = (answer + fact[remaining] * subtotal) % MOD
                ones += 1
        return answer

