import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    rows = [0] * n
    for k in range(m):
        u, v = data[2 + 2*k] - 1, data[3 + 2*k] - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduce the adjacency matrix over GF(2).
    pivots = []
    rank = 0
    for col in range(n):
        bit = 1 << col
        p = next((i for i in range(rank, n) if rows[i] & bit), -1)
        if p == -1:
            continue
        rows[rank], rows[p] = rows[p], rows[rank]
        for i in range(n):
            if i != rank and rows[i] & bit:
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [i for i in range(n) if i not in pivot_set]
    ans = [0] * n
    offset = min(2, 60 - len(free)) if m else 0
    # Separate bits encode all nullspace basis vectors simultaneously.
    for j, col in enumerate(free):
        ans[col] = 1 << (j + offset)
    for r, col in enumerate(pivots):
        for f in free:
            if rows[r] & (1 << f):
                ans[col] ^= ans[f]

    # A zero coordinate here is zero in every nullspace vector.
    if any(x == 0 for x in ans):
        print('No')
    else:
        print('Yes')
        print(*ans)


if __name__ == '__main__':
    main()

