import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, k = data[:3]
    x = data[3:]
    d = sum(x[i] != x[i + 1] for i in range(m - 1))
    length = n - (m * k - 1 + d)
    if length < 0:
        print(0)
        return

    dp = [1] + [0] * length
    for j in range(1, k):
        for _ in range(m):
            for t in range(1, length + 1):
                dp[t] = (dp[t] + j * dp[t - 1]) % MOD
    for _ in range(d):
        for t in range(1, length + 1):
            dp[t] = (dp[t] + (k - 2) * dp[t - 1]) % MOD

    fact = 1
