class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        if k in (1, 3, 9):
            return '9' * n

        if k in (2, 5):
            edge = '8' if k == 2 else '5'
            return edge if n == 1 else edge + '9' * (n - 2) + edge

        if k in (4, 8):
            width = 2 if k == 4 else 3
            if n <= 2 * width:
                return '8' * n
            return '8' * width + '9' * (n - 2 * width) + '8' * width

        if k == 6:
            if n <= 2:
                return '6' * n
            if n % 2:
                side = '9' * (n // 2 - 1)
                return '8' + side + '8' + side + '8'
            side = '9' * (n // 2 - 2)
            return '8' + side + '77' + side + '8'

        # For k = 7, only the central digit or central pair needs changing.
        remainder = (pow(10, n, 7) - 1) % 7
        if n % 2:
            coefficient = pow(10, n // 2, 7)
        else:
            coefficient = 11 * pow(10, n // 2 - 1, 7) % 7
        for digit in range(9, -1, -1):
            if (remainder - (9 - digit) * coefficient) % 7 == 0:
                side = '9' * ((n - 1) // 2)
                return side + str(digit) * (1 if n % 2 else 2) + side

