import random,time

def solve(nums,k):
    groups=deque();right=len(nums)-1;cost=0;answer=0
    for left in range(len(nums)-1,-1,-1):
        value=nums[left];count=1
        while groups and groups[0][0]<=value:
            old,size=groups.popleft();cost+=(value-old)*size;count+=size
        groups.appendleft([value,count])
        while cost>k:
            group=groups[-1];cost-=group[0]-nums[right];right-=1;group[1]-=1
            if group[1]==0:groups.pop()
        answer+=right-left+1
    return answer

