class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        grouped = [[] for _ in range(n)]
        for k, (l, r) in enumerate(queries):
            grouped[l].append((r, k))
        answer = [0] * len(queries)
        scores = [0] * n
        best = [0] * n
        for l in range(n - 1, -1, -1):
            value = nums[l]
            maximum = value
            scores[l] = value
            best[l] = value
            for r in range(l + 1, n):
                value ^= scores[r]
                scores[r] = value
                if best[r] > maximum:
                    maximum = best[r]
                if value > maximum:
                    maximum = value
                best[r] = maximum
            for r, k in grouped[l]:
                answer[k] = best[r]
        return answer

class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1
        answer = len(s)
        for target in range(1, max(counts) + 1):
            drop = keep = 0
            previous = 0
            for count in counts:
                best = min(drop, keep)
                new_drop = best + count
                if count >= target:
                    new_keep = best + count - target
                else:
                    deficit = target - count
                    new_keep = min(
                        drop + max(0, deficit - previous),
                        keep + max(0, deficit - max(0, previous - target))
                    )
                drop, keep = new_drop, new_keep
                previous = count
            answer = min(answer, drop, keep)
        return answer

