from functools import lru_cache


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, l = data[:3]
    values = data[3:]
    k = n + m + l
    full = (1 << k) - 1

    lower = []
    for value in values:
        mask = 0
        for j, other in enumerate(values):
            if other < value:
                mask |= 1 << j
        lower.append(mask)

    @lru_cache(maxsize=None)
    def win(hand, opponent):
        if not hand:
            return False
        if not opponent:
            return True

        table = full ^ (hand | opponent)
        remaining = hand
        while remaining:
            played = remaining & -remaining
            remaining -= played
            next_hand = hand ^ played

            if not win(opponent, next_hand):
                return True

            choices = table & lower[played.bit_length() - 1]
            while choices:
                taken = choices & -choices
                choices -= taken
                if not win(opponent, next_hand | taken):
                    return True
        return False

    takahashi = (1 << n) - 1
    aoki = ((1 << m) - 1) << n
    print('Takahashi' if win(takahashi, aoki) else 'Aoki')


