class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        parts = p.split('*')

        def occurrences(t):
            m = len(t)
            if m == 0:
                return range(n + 1)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        a, b, c = map(occurrences, parts)
        la, lb, lc = map(len, parts)
        j = k = 0
        best = n + 1
        for start in a:
            while j < len(b) and b[j] < start + la:
                j += 1
            if j == len(b):
                break
            while k < len(c) and c[k] < b[j] + lb:
                k += 1
            if k == len(c):
                break
            best = min(best, c[k] + lc - start)
        return best if best <= n else -1

