import sys

def solve(n, a, b):
    if a == b:
        return 0
    aa = [i + 1 for i, c in enumerate(a) if c == 49]
    bb = [i + 1 for i, c in enumerate(b) if c == 49]
    m = len(aa)
    if len(bb) > m:
        return -1
    if len(bb) == 1:
        return max(abs(aa[0] - bb[0]), abs(aa[-1] - bb[0]))
    first = bb[0]
    last = bb[-1]
    end = aa[-1]
    steps = [(bb[i] - bb[i - 1] - 1, bb[i]) for i in range(1, len(bb))]

    def check(k):
        lo = first - 1 - k
        if lo >= aa[0]:
            return False
        lo = max(lo + 1, aa[0])
        lo += (first + k - lo) & 1
        if lo > first + k:
            return False
        idx = 0
        for z, y in steps:
            while idx < m and aa[idx] <= lo:
                idx += 1
            if z:
                p = lo
                hi = y - z - 1 + k
                while idx < m and p + z >= aa[idx]:
                    p = aa[idx]
                    p += (lo - p) & 1
                    if p > hi:
                        return False
                    idx += 1
                    if idx < m and aa[idx] <= p:
                        idx += 1
                if idx == m or p > hi:
                    return False
                lo = p + z
            while idx < m and aa[idx] <= lo:
                idx += 1
            if idx == m:
                return False
            v = aa[idx]
            lo = lo + 1 if lo >= v else v
            lo += (y + k - lo) & 1
            if lo > y + k:
                return False
        r = lo if lo >= end else end
        return r + ((last + k - r) & 1) <= last + k

    def possible(k):
        return check(k) or (k > 0 and check(k - 1))

    low = max(abs(aa[0] - first), abs(end - last))
    if possible(low):
        return low
    high = 2 * n
    if not possible(high):
        return -1
    while low + 1 < high:
        mid = (low + high) // 2
        if possible(mid):
            high = mid
        else:
            low = mid
    return high


