class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1

        # Rotate the alphabet's interpretation rather than moving counts.
        z = 25
        for _ in range(t):
            b = (z + 1) % 26
            counts[b] = (counts[b] + counts[z]) % MOD
            z = (z - 1) % 26

        return sum(counts) % MOD

