from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        reachable = [1] * n
        masks = [(1 << (x + 1)) - 1 for x in nums]
        done = [x == 0 for x in nums]
        remaining = sum(not x for x in done)
        if remaining == 0:
            return 0

        for k, (l, r, val) in enumerate(queries, 1):
            for i in range(l, r + 1):
                if done[i]:
                    continue
                reachable[i] = (reachable[i] | (reachable[i] << val)) & masks[i]
                if (reachable[i] >> nums[i]) & 1:
                    done[i] = True
                    remaining -= 1
            if remaining == 0:
                return k
        return -1

