from heapq import heappush, heappop

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10 ** len(str(n))
        low = limit // 10
        prime = bytearray(b'\x01') * limit
        prime[0:2] = b'\x00\x00'
        for p in range(2, int((limit - 1) ** 0.5) + 1):
            if prime[p]:
                start = p * p
                prime[start:limit:p] = b'\x00' * ((limit - 1 - start) // p + 1)
        if prime[n] or prime[m]:
            return -1
        dist = [float('inf')] * limit
        dist[n] = n
        heap = [(n, n)]
        places = []
        p = 1
        while p < limit:
            places.append(p)
            p *= 10
        while heap:
            cost, x = heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost
            for p in places:
                digit = x // p % 10
                if digit < 9:
                    y = x + p
                    if not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heappush(heap, (cost + y, y))
                if digit > 0:
                    y = x - p
                    if y >= low and not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heappush(heap, (cost + y, y))
        return -1

