from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        positions = [[] for _ in range(26)]
        for j in range(m - 1, -1, -1):
            positions[ord(pattern[j]) - 97].append(j)

        removable = bytearray(len(source))
        for i in targetIndices:
            removable[i] = 1

        # dp[j]: minimum removable positions used to match pattern[:j].
        dp = [len(source) + 1] * (m + 1)
        dp[0] = 0
        for i, c in enumerate(source):
            cost = removable[i]
            # Descending order prevents using a source character twice.
            for j in positions[ord(c) - 97]:
                value = dp[j] + cost
                if value < dp[j + 1]:
                    dp[j + 1] = value

        return len(targetIndices) - dp[m]

