from typing import List
import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # A reverse spanning tree needs only one outgoing edge per
        # non-root node in the original graph, so threshold >= 1 suffices.
        reverse = [[] for _ in range(n)]
        for a, b, w in edges:
            reverse[b].append((a, w))

        dist = [1000001] * n
        dist[0] = 0
        heap = [(0, 0)]
        remaining = n

        while heap:
            cost, u = heapq.heappop(heap)
            if cost != dist[u]:
                continue
            remaining -= 1
            if remaining == 0:
                return cost
            for v, w in reverse[u]:
                candidate = max(cost, w)
                if candidate < dist[v]:
                    dist[v] = candidate
                    heapq.heappush(heap, (candidate, v))

        return -1

